import{_ as a,c as o,o as d,ae as i}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Using Commands","description":"How to use commands to play audio in MinecraftSounds","frontmatter":{"title":"Using Commands","description":"How to use commands to play audio in MinecraftSounds"},"headers":[],"relativePath":"en/tutorials/command.md","filePath":"en/tutorials/command.md"}'),l={name:"en/tutorials/command.md"};function r(n,e,s,t,c,u){return d(),o("div",null,e[0]||(e[0]=[i('<h1 id="using-commands-to-play-audio" tabindex="-1">Using Commands to Play Audio <a class="header-anchor" href="#using-commands-to-play-audio" aria-label="Permalink to &quot;Using Commands to Play Audio&quot;">​</a></h1><p>For version 1.7.10 and below:<br><code>/playsound {soundkey} {player name/target selector} {x} {y} {z} {play range/radius}</code><br> For version 1.8 and above:<br><code>/playsound {soundkey} {sound source} {player name/target selector} {x} {y} {z} {play range/radius}</code></p><h2 id="soundkey" tabindex="-1">soundkey <a class="header-anchor" href="#soundkey" aria-label="Permalink to &quot;soundkey&quot;">​</a></h2><p>For details, visit the <a href="/en/tutorials/soundkey.html">Understanding soundkey</a> page.</p><h2 id="sound-source" tabindex="-1">Sound Source <a class="header-anchor" href="#sound-source" aria-label="Permalink to &quot;Sound Source&quot;">​</a></h2><ul><li><code>master</code>: Master volume</li><li><code>music</code>: Music volume</li><li><code>record</code>: Record player [Default choice]</li><li><code>weather</code>: Weather</li><li><code>block</code>: Block</li><li><code>neutral</code>: Neutral entity</li><li><code>player</code>: Player</li><li><code>ambient</code>: Environment</li><li><code>voice</code>: Player voice [Only in higher versions]</li><li><code>ui</code>: User interface [Only in higher versions]</li></ul><h2 id="target-selector" tabindex="-1">Target Selector <a class="header-anchor" href="#target-selector" aria-label="Permalink to &quot;Target Selector&quot;">​</a></h2><ul><li><code>@a</code>: All players</li><li><code>@p</code>: Nearest player</li><li><code>@r</code>: Random player</li><li><code>@s</code>: Command executor</li></ul><h2 id="coordinates" tabindex="-1">Coordinates <a class="header-anchor" href="#coordinates" aria-label="Permalink to &quot;Coordinates&quot;">​</a></h2><ul><li><code>x</code>: X-coordinate for audio playback</li><li><code>y</code>: Y-coordinate for audio playback</li><li><code>z</code>: Z-coordinate for audio playback</li></ul><h2 id="play-range-radius" tabindex="-1">Play Range/Radius <a class="header-anchor" href="#play-range-radius" aria-label="Permalink to &quot;Play Range/Radius&quot;">​</a></h2><ul><li>Play range: The range of audio playback, measured in blocks.</li><li>Radius: The radius of audio playback, measured in blocks.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><ul><li>For version 1.7.10 and below:<br><code>/playsound mcsd.my_sound @a ~ ~ ~ 10000</code></li><li>For version 1.8 and above:<br><code>/playsound mcsd.my_sound record @a ~ ~ ~ 10000</code></li></ul><hr><h1 id="using-commands-to-stop-audio" tabindex="-1">Using Commands to Stop Audio <a class="header-anchor" href="#using-commands-to-stop-audio" aria-label="Permalink to &quot;Using Commands to Stop Audio&quot;">​</a></h1><p>For version 1.8 and above:<br><code>/stopsound @a</code></p>',17)]))}const p=a(l,[["render",r]]);export{h as __pageData,p as default};
